<?php require 'includes/auth.php';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'customer')");try{$s->execute([$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT)]);$_SESSION['uid']=$pdo->lastInsertId();header('Location: account.php');exit;}catch(Exception $e){$err='Email sudah terdaftar.';}}?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><link rel=stylesheet href=assets/style.css><title>Daftar</title></head><body><main class=checkout><h1>Daftar Member</h1><?php if(isset($err))echo '<p class=err>'.e($err).'</p>';?><form method=post><input name=name required placeholder="Nama"><input type=email name=email required placeholder="Email"><input type=password name=password required placeholder="Password minimal 6 karakter"><button class=btn>Daftar</button></form></main></body></html>
